// Diff freshly scraped prices vs the live index; emit moves + full payload
const scraped = $('LLM: extract price table').all().flatMap(i => i.json.message?.content?.models || i.json.models || []);
const live = $('Fetch current index').first().json;
const liveRows = (live.providers || []).flatMap(p => p.models.map(m => ({...m, provider: p.provider})));
const moves = [];
for (const s of scraped) {
  const prev = liveRows.find(r => r.model.toLowerCase() === s.model.toLowerCase());
  if (prev && (Math.abs(prev.input_per_1m - s.input_per_1m) > 1e-9 || Math.abs(prev.output_per_1m - s.output_per_1m) > 1e-9)) {
    const pct = Math.round(100 * (s.output_per_1m - prev.output_per_1m) / prev.output_per_1m);
    moves.push({ model: s.model, from: prev.output_per_1m, to: s.output_per_1m, delta_pct: pct });
  }
}
return [{ json: { changed: moves.length > 0, moves, scraped } }];
